#include <metal_stdlib>
using namespace metal;

// A continuous shower of red strawberries with green calyxes and tiny seeds.
struct ShaderUniforms {
    float4 resolutionTime; // width, height, seconds, unused
    float4 mouse;          // reserved by the shader-state contract
};

float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}

float noise2(float2 p) {
    float2 cell = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(cell), hash21(cell + float2(1.0, 0.0)), f.x),
               mix(hash21(cell + float2(0.0, 1.0)),
                   hash21(cell + float2(1.0, 1.0)), f.x), f.y);
}

float3 berryColor(float2 p, float width, float seed, float yaw) {
    // Treat the front of the pear-shaped body as a rounded 3D surface.
    float u = clamp(p.x / max(width, 0.05), -0.999, 0.999);
    float v = clamp((p.y + 0.12) / 1.05, -0.98, 0.98);
    float depth = sqrt(max(0.0, 1.0 - u * u))
                  * sqrt(max(0.0, 1.0 - v * v));
    float3 surfaceNormal = normalize(float3(0.95 * u, 0.73 * v,
                                             1.30 * depth + 0.025));
    float cs = cos(yaw), sn = sin(yaw);
    float3 normal = float3(cs * surfaceNormal.x + sn * surfaceNormal.z,
                            surfaceNormal.y,
                            -sn * surfaceNormal.x + cs * surfaceNormal.z);
    float3 lightDirection = normalize(float3(-0.58, 0.73, 0.63));
    float diffuse = max(dot(normal, lightDirection), 0.0);
    float wrappedLight = clamp((dot(normal, lightDirection) + 0.35) / 1.35,
                               0.0, 1.0);
    float grain = noise2(p * 21.0 + seed * 37.0);
    float3 red = mix(float3(0.68, 0.055, 0.065),
                     float3(0.82, 0.105, 0.085), seed);
    float3 color = red * (0.27 + 0.79 * wrappedLight)
                   * (0.91 + 0.15 * grain);
    color *= 1.0 - 0.19 * smoothstep(0.38, 0.72, p.y);
    color += float3(0.13, 0.019, 0.010)
             * pow(1.0 - depth, 2.0) * (0.5 + 0.5 * diffuse);

    // Project the staggered seed rows around the curved surface. As the
    // berry turns, seeds move across its face instead of staying painted on.
    float longitude = atan2(u, max(depth, 0.02)) + yaw;
    float row = floor((p.y + 0.92) * 8.0);
    float2 seedUV = float2(longitude * 3.7 + fract(row * 0.5),
                           (p.y + 0.92) * 8.0);
    float2 cell = floor(seedUV);
    float2 jitter = (float2(hash21(cell + float2(13.0, seed)),
                            hash21(cell + float2(seed, 47.0))) - 0.5) * 0.16;
    float2 mark = (fract(seedUV) - 0.5 - jitter) / float2(0.18, 0.26);
    float seedShape = length(mark);
    float dimple = 1.0 - smoothstep(1.0, 1.42, seedShape);
    float achene = 1.0 - smoothstep(0.63, 0.94, seedShape);
    color *= 1.0 - 0.28 * dimple;
    color = mix(color, float3(0.88, 0.66, 0.33)
                       * (0.68 + 0.34 * diffuse), achene * 0.92);

    float3 halfVector = normalize(lightDirection + float3(0.0, 0.0, 1.0));
    float gloss = pow(max(dot(normal, halfVector), 0.0), 38.0);
    color += float3(0.43, 0.27, 0.20) * gloss;
    return color;
}

// The calyx is a ring of leaves in 3D. Yaw changes which leaves are in front.
float3 drawCalyx(float3 color, float2 p, float yaw, float aa,
                  bool drawFront) {
    float cs = cos(yaw), sn = sin(yaw);
    float2 base = float2(sn * 0.18, 0.68);
    for (int leaf = 0; leaf < 5; ++leaf) {
        float angle = 6.2831853 * float(leaf) / 5.0;
        float3 tip3 = float3(0.65 * sin(angle), 0.0,
                             0.65 * cos(angle));
        float depth = -sn * tip3.x + cs * tip3.z;
        if ((depth >= 0.0) != drawFront) continue;
        float2 tip = float2(cs * tip3.x + sn * tip3.z,
                            0.80 - 0.62 * max(tip3.z, 0.0)
                            + 0.04 * max(-tip3.z, 0.0));
        float2 axis = tip - base;
        float t = clamp(dot(p - base, axis) / max(dot(axis, axis), 0.01),
                        0.0, 1.0);
        float2 fromVein = p - (base + t * axis);
        float leafWidth = 0.018 + 0.14 * sin(3.14159265 * t);
        float leafEdge = length(fromVein) - leafWidth;
        float coverage = 1.0 - smoothstep(-aa, aa, leafEdge);
        float signedSide = (axis.x * fromVein.y - axis.y * fromVein.x)
                           / max(length(axis), 0.01);
        float arch = clamp(abs(signedSide) / leafWidth, 0.0, 1.0);
        float leafLight = clamp(0.55 + 0.35 * sqrt(1.0 - arch * arch)
                                + 0.18 * depth / 0.65
                                - 0.12 * signedSide / leafWidth,
                                0.33, 1.18);
        float vein = 1.0 - smoothstep(0.012, 0.037, length(fromVein));
        float3 green = float3(0.13, 0.46, 0.11) * leafLight
                       * (0.95 + 0.12 * t);
        green += float3(0.12, 0.21, 0.045) * vein * 0.48;
        color = mix(color, green, coverage);
    }
    return color;
}

float3 renderStrawberryRain(float2 screen, float2 resolution, float time) {
    float aspect = resolution.x / resolution.y;
    float sky = smoothstep(-1.2, 1.2, screen.y);
    float3 color = mix(float3(0.91, 0.86, 0.75),
                       float3(0.66, 0.81, 0.76), sky);
    color += (noise2(screen * 85.0) - 0.5) * 0.012;

    // Staggered phases give a steady stream while each fruit tumbles and sways.
    for (int i = 0; i < 32; ++i) {
        float index = float(i);
        float seed = hash21(float2(index, 19.7));
        float size = 0.090 + 0.080 * index / 31.0
                     + 0.019 * hash21(float2(index, 8.3));
        float speed = 0.16 + 0.095 * hash21(float2(index, 5.1));
        float phase = fract((index + 0.5) / 32.0 + time * speed);
        float2 center = float2(
            (2.0 * hash21(float2(index, 13.4)) - 1.0) * (aspect - 0.03)
                + 0.10 * sin(time * (0.8 + seed) + index * 2.3),
            1.32 - 2.66 * phase);
        float2 delta = screen - center;
        if (abs(delta.x) > size * 1.25 || abs(delta.y) > size * 1.25)
            continue;

        float rotation = time * (0.75 + seed * 0.80) + index * 2.4;
        float c = cos(rotation), s = sin(rotation);
        float2 p = float2(c * delta.x + s * delta.y,
                          -s * delta.x + c * delta.y) / size;
        float yaw = 0.75 * sin(time * (0.8 + seed * 0.6) + index * 1.1);
        float horizontalScale = 0.70 + 0.30 * cos(yaw);
        float aa = max(2.0 / (resolution.y * size), 0.008);

        // Wide shoulders taper smoothly into the pointed strawberry tip.
        float rise = clamp((p.y + 1.02) / 1.15, 0.0, 1.0);
        float width = 0.82 * pow(rise, 0.72)
                      * (1.0 - 0.18 * smoothstep(0.40, 0.75, p.y))
                      * horizontalScale;
        float bodyEdge = max(abs(p.x) - width,
                             max(p.y - 0.72, -1.02 - p.y));
        float body = 1.0 - smoothstep(-aa, aa, bodyEdge);
        color = drawCalyx(color, p, yaw, aa, false);
        if (body > 0.0)
            color = mix(color, berryColor(p, width, seed, yaw), body);

        // Rear leaves are covered by the fruit; front leaves overlap it.
        color = drawCalyx(color, p, yaw, aa, true);
        float2 crownCenter = float2(sin(yaw) * 0.18, 0.68);
        float crown = 1.0 - smoothstep(0.10 - aa, 0.10 + aa,
                                       length(p - crownCenter));
        color = mix(color, float3(0.18, 0.43, 0.12), crown);

        // The stem shares the crown's 3D turn instead of staying in place.
        float cs = cos(yaw), sn = sin(yaw);
        float2 stemStart = float2(sn * 0.16, 0.70);
        float2 stemEnd = float2(cs * 0.13 + sn * 0.03, 1.14);
        float2 stemAxis = stemEnd - stemStart;
        float stemT = clamp(dot(p - stemStart, stemAxis)
                            / dot(stemAxis, stemAxis), 0.0, 1.0);
        float stemDistance = length(p - (stemStart + stemT * stemAxis));
        float stem = 1.0 - smoothstep(0.035 - aa, 0.035 + aa,
                                     stemDistance);
        float stemLight = clamp(0.78 + 0.25 * cs
                                - 1.8 * (p.x - stemStart.x), 0.55, 1.18);
        color = mix(color, float3(0.18, 0.36, 0.10) * stemLight, stem);
    }
    return clamp(color, float3(0.0), float3(1.0));
}

vertex float4 fullscreenVertex(uint vertexID [[vertex_id]]) {
    float2 p = float2((vertexID << 1) & 2, vertexID & 2);
    return float4(p * 2.0 - 1.0, 0.0, 1.0);
}

fragment float4 strawberryRainFragment(
    float4 position [[position]], constant ShaderUniforms &uniforms [[buffer(0)]]) {
    float2 resolution = uniforms.resolutionTime.xy;
    float2 frag = float2(position.x, resolution.y - position.y);
    float2 screen = (frag - 0.5 * resolution) * (2.0 / resolution.y);
    return float4(renderStrawberryRain(screen, resolution,
                                       uniforms.resolutionTime.z), 1.0);
}
